#!/bin/bash
PID=$(pgrep -f 'node.*server\.js' | head -1)
echo "Node PID: $PID"

# Get JWT_SECRET
JWT_SECRET=$(cat /proc/$PID/environ | tr '\0' '\n' | grep '^JWT_SECRET=' | cut -d= -f2-)
DATABASE_URL=$(cat /proc/$PID/environ | tr '\0' '\n' | grep '^DATABASE_URL=' | cut -d= -f2-)

# Generate token
TOKEN=$(node -e "
const jwt=require('/var/app/current/node_modules/jsonwebtoken');
const {Client}=require('/var/app/current/node_modules/pg');
const {v4:uv}=require('/var/app/current/node_modules/uuid');
const {execSync}=require('child_process');
const pid=execSync(\"pgrep -f 'node.*server\\.js' | head -1\").toString().trim();
const env=require('fs').readFileSync('/proc/'+pid+'/environ','utf8');
const vars=Object.fromEntries(env.split(String.fromCharCode(0)).filter(Boolean).map(e=>{const i=e.indexOf('=');return[e.slice(0,i),e.slice(i+1)];}));
(async()=>{
  const db=new Client({connectionString:vars.DATABASE_URL,ssl:{rejectUnauthorized:false}});
  await db.connect();
  const {rows}=await db.query(\"SELECT u->>'id' AS id, u->>'role' AS role, u->>'teamId' AS tid FROM app_state s, jsonb_array_elements(s.data->'users') u WHERE u->>'email'='medico.teste@vitras.com.br'\");
  await db.end();
  const u=rows[0];
  const tok=jwt.sign({jti:uv(),sessionId:uv(),id:u.id,name:'Medico',role:u.role,email:'medico.teste@vitras.com.br',teamId:u.tid,teamName:'',unitId:'unit-default',municipalityId:'',capabilities:{},impersonation:null,breakGlass:null},vars.JWT_SECRET,{algorithm:'HS256',issuer:'vitras-backend',audience:'vitras-client',expiresIn:'2h'});
  process.stdout.write(tok);
})().catch(e=>{process.stderr.write(e.message);process.exit(1);});
" 2>/tmp/gen-err.txt)
echo "Token len: ${#TOKEN}"
cat /tmp/gen-err.txt

# Test 1: POST with inline body (no file)
echo "=== Test 1: POST /patients inline body ==="
RESULT1=$(curl -s --max-time 5 -o /tmp/r1.txt -w "CODE:%{http_code} SIZE:%{size_download} TIME:%{time_total}" \
  -X POST \
  -H "Authorization: Bearer $TOKEN" \
  -H "Content-Type: application/json" \
  --data '{"name":"FC10 Test","phone":"(11) 99999-9999","cpf":"","cns":"","dataNascimento":"1990-01-01","sexo":"M","address":"Rua Test 100 Centro SP","microArea":"A"}' \
  http://localhost:8080/patients 2>&1) || true
echo "curl exit: $?"
echo "Result: $RESULT1"
cat /tmp/r1.txt 2>/dev/null || echo "(no resp file)"

# Test 2: GET /me (sanity)
echo "=== Test 2: GET /me ==="
RESULT2=$(curl -s --max-time 5 -o /tmp/r2.txt -w "CODE:%{http_code} SIZE:%{size_download} TIME:%{time_total}" \
  -H "Authorization: Bearer $TOKEN" \
  http://localhost:8080/me 2>&1) || true
echo "Result: $RESULT2"
cat /tmp/r2.txt 2>/dev/null | head -c 100

rm -f /tmp/r1.txt /tmp/r2.txt /tmp/gen-err.txt
